# -*- coding: utf-8 -*-
"""docs/4.2-排期表.docx —— 按 game-docs-and-sheets-inventory.md 4.2 写。

清单要求：把 WBS 排到周、给里程碑、缓冲、延期规则。
事实来源：docs/4.1-WBS.docx 的 10 个工作包与 20h 总盘、1.3 的「不设死线」、1.4 的「触发条件代替日期」。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "4.2-排期表.docx")


def main():
    doc = k.new_doc("4.2 排期表 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器 · 排期表",
        "5 周排到投稿 · v0.1 · 2026-11-04",
    )

    k.note(
        doc,
        "**没有日期，只有周次。** 1.3 里已经定了不设死线，所以「第 3 周」= 「你第三个 5 小时」，"
        "不是某个日历日。每周只要求一件事：**周末有个能验的东西**。",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "五周排期")
    k.table(
        doc,
        ["周", "本周任务", "工时", "周末交付", "周末验收（你自己看）"],
        [
            ["第 1 周", "W4.1 文档收尾 + W4.4 数值打通", "5h", "ADR 6 条、发布检查单、`gen:config` 能跑",
             "改 `P3-数值总表.xlsx` 一个数 → 重生成 → 单测过 → 游戏里生效"],
            ["第 2 周", "W4.2 事件 34 → 48 条", "5h", "14 条新事件进游戏",
             "连开 3 局，每局至少碰到 2 条没见过的"],
            ["第 3 周", "W4.2 收尾（→60）+ W4.3 UI 收口", "5h", "事件 60 条、字号 3 级、加载态 10 屏",
             "截图对照 2.6 的色板；字号只剩 16/15/12"],
            ["第 4 周", "W5.1 真机 + W5.2 修 + W6.1 素材 + W6.2 投稿", "4.5h", "手机能玩、素材齐、投稿提交",
             "中低端安卓冷开不白屏；审核回执到手"],
            ["第 5 周", "**缓冲**", "5h", "修第 4 周暴露的问题 / 补 W6.3 复盘", "投稿通过，或问题清单清空"],
        ],
        [1.6, 5.4, 1.2, 4.6, 8.2],
        size=8,
        caption="表 1-1　合计 19.5h，留 5h 缓冲＝25%，比 4.1 的 20h 多出的部分就是缓冲",
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "里程碑（不看日期，看条件）")
    k.table(
        doc,
        ["里程碑", "条件（满足才算到）", "在哪周"],
        [
            ["M1 文档齐", "发布检查单能一条条打勾；ADR 至少 6 条；gen:config 改表即生效", "第 1 周末"],
            ["M2 内容够", "事件 ≥ 50 条且连开 3 局不重样太多；UI 只剩 3 级字号", "第 3 周末"],
            ["M3 能投", "真机走完 10 项；素材齐；单文件 ≤150KB", "第 4 周末"],
            ["M4 上线", "平台审核通过 + 手机流量能开 + 刷新不丢档", "第 5 周内"],
        ],
        [3.0, 12.6, 3.8],
        size=9,
    )

    # ---------------- 三 ----------------
    k.h1(doc, "三", "本周没做完怎么办（滚动规则）")
    k.table(
        doc,
        ["情况", "动作"],
        [
            ["某周只做了 2h", "把未完成的整包推到下周，**不要拆开做一半**"],
            ["事件写不动（W4.2 卡住）", "先保 48 条，60 条降级为「首发后补」；**内容不能低于 48**"],
            ["真机借不到（W5.1 卡住）", "借不到就用自己手机 + Chrome 设备模拟，但**必须在文档里标明「未在低端机验证」**"],
            ["审核超过 3 个工作日", "不加急、不改动作，等；这段时间做 W6.3 预演"],
            ["连卡两周", "触发 1.3 的砍序：先砍内容（事件 60→48），再砍表现（加载态），**不砍真机**"],
        ],
        [7.4, 12.0],
        size=9,
    )

    # ---------------- 四 ----------------
    k.h1(doc, "四", "风险与缓冲")
    k.table(
        doc,
        ["风险", "概率", "缓冲在哪"],
        [
            ["事件写不出来（梗用完了）", "中", "第 5 周缓冲；素材表里还有 520 + 1000 条梗可挖"],
            ["真机问题比预想多（白屏/滚动）", "中", "W5.2 只留 1.5h，很可能不够 → 吃掉第 5 周"],
            ["平台审核退回（素材不合规）", "低", "第 4 周先查规范再出图"],
            ["UI 收口牵扯布局回归", "中", "字号改小会挤爆行动格 → 可能触发 W4.3 返工"],
            ["数值表与代码打通时发现表本身有错", "高", "第 1 周就做，早暴露"],
        ],
        [8.4, 2.6, 8.4],
        size=9,
    )
    k.para(
        doc,
        "**这张表最容易骗人的地方**：5 周是「每周都按计划做满 5h」算出来的。"
        "现实里开会、加班、生病都会吃掉 1–2h，所以缓冲不是慷慨，是必需的。",
    )

    # ---------------- 五 ----------------
    k.h1(doc, "五", "每周怎么用（一句话版）")
    k.table(
        doc,
        ["时段", "做什么"],
        [
            ["开始（10 分钟）", "打开 4.1 找一个包，贴进对话说「做 Wxx」"],
            ["中间", "只做这一个包，不加需求"],
            ["结束（10 分钟）", "按「周末验收」那一列自己验一遍，过了就提交"],
        ],
        [4.0, 15.0],
        size=9,
    )

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
